// BFS Level Order Traversal on Graph using Queue
var queue = AnimatedQueue<String>()
queue.enqueue("A")

let graph = [
    "A": ["B", "C"],
    "B": ["D"],
    "C": [],
    "D": []
]

var visited: [String] = []

while !queue.isEmpty {
    if let current = queue.dequeue() {
        visited.append(current)
        if let neighbors = graph[current] {
            for neighbor in neighbors {
                queue.enqueue(neighbor)
            }
        }
    }
}
